    throw new TypeError('qs must be a string');
  }

  const result = {};
  const params = qs.replace(/^\?/, '').split('&');

  for (const param of params) {
    if (param === '') continue;

    let [key, value] = param.split('=', 2);

    // Decode key and value
    try {
      key = decodeURIComponent(key.replace(/\+/g, ' '));
      if (value !== undefined) {
        value = decodeURIComponent(value.replace(/\+/g, ' '));
      }
    } catch (e) {
      if (e instanceof URIError) {
        throw e;
      }
      throw new URIError('Malformed URI');
    }

    // Skip empty keys
    if (key === '') continue;

    // Handle multiple values
    if (result.hasOwnProperty(key)) {
      if (Array.isArray(result[key])) {
        result[key].push(value === undefined ? '' : value);
      } else {
        result[key] = [result[key], value === undefined ? '' : value];
      }
    } else {
      result[key] = value === undefined ? '' : value;
    }
  }

  return result;
}

module.exports = { parseQuery };
