function topoSort(graph) {
  // Create a deep copy of the graph to avoid modifying the original
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys and referenced tasks)
  const allTasks = new Set();
  for (const task in graphCopy) {
    allTasks.add(task);
    for (const dep of graphCopy[task]) {
      allTasks.add(dep);
    }
  }

  // Calculate in-degrees for each task
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = 0;
  }

  for (const task in graphCopy) {
    for (const dep of graphCopy[task]) {
      inDegree[dep]++;
    }
  }

  // Find all tasks with no dependencies
  const readyTasks = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks lexicographically
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Pick the lexicographically smallest task
    const current = readyTasks.shift();
    result.push(current);

    // Remove current task and update in-degrees
    for (const task in graphCopy) {
      const index = graphCopy[task].indexOf(current);
      if (index !== -1) {
        graphCopy[task].splice(index, 1);
        inDegree[task]--;

        // If task now has no dependencies, add to ready tasks
        if (inDegree[task] === 0) {
          readyTasks.push(task);
          readyTasks.sort(); // Keep sorted
        }
      }
    }
  }

  // Check for cycles - if we haven't placed all tasks, there's a cycle
  if (result.length !== allTasks.size) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
