  // Create a copy of the graph to avoid modifying the original
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys + tasks in dependencies)
  const allTasks = new Set();
  for (const key in graphCopy) {
    allTasks.add(key);
    for (const dep of graphCopy[key]) {
      allTasks.add(dep);
    }
  }

  // Build dependency count map
  const depCount = new Map();
  for (const task of allTasks) {
    depCount.set(task, 0);
  }

  // Count dependencies for each task
  for (const key in graphCopy) {
    for (const dep of graphCopy[key]) {
      depCount.set(dep, depCount.get(dep) + 1);
    }
  }

  // Find tasks with no dependencies
  const readyTasks = [];
  for (const task of allTasks) {
    if (depCount.get(task) === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks lexicographically
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Pick the smallest task name
    const currentTask = readyTasks.shift();
    result.push(currentTask);

    // Remove this task from dependencies of others
    for (const key in graphCopy) {
      const deps = graphCopy[key];
      const index = deps.indexOf(currentTask);
      if (index !== -1) {
        deps.splice(index, 1);
        depCount.set(key, depCount.get(key) - 1);

        // If this task now has no dependencies, add it to ready tasks
        if (depCount.get(key) === 0) {
          readyTasks.push(key);
          readyTasks.sort();
        }
      }
    }
  }

  // Check for cycles
  if (result.length !== allTasks.size) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
