def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        raise ValueError("empty string")

    # Define valid units and their seconds values
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = ['d', 'h', 'm', 's']

    # Track which units we've seen
    seen_units = set()

    # Track position in string
    pos = 0
    total_seconds = 0

    while pos < len(text):
        # Find the number part
        if not text[pos].isdigit():
            raise ValueError("invalid format")

        # Parse the number
        num_start = pos
        while pos < len(text) and text[pos].isdigit():
            pos += 1

        number_str = text[num_start:pos]

        # Check for empty number
        if not number_str:
            raise ValueError("missing number")

        # Convert to integer
        try:
            number = int(number_str)
        except ValueError:
            raise ValueError("invalid number format")

        # Check for unit
        if pos >= len(text):
            raise ValueError("missing unit")

        unit = text[pos]

        # Validate unit
        if unit not in units:
            raise ValueError("unknown unit")

        # Check if unit has been seen before
        if unit in seen_units:
            raise ValueError("repeated unit")

        # Check if unit order is valid (must be in descending order)
        if seen_units:
            last_unit = None
            for u in unit_order:
                if u in seen_units:
                    last_unit = u
                    break
            if last_unit and unit_order.index(unit) > unit_order.index(last_unit):
                raise ValueError("out-of-order unit")

        # Add to seen units
        seen_units.add(unit)

        # Add to total seconds
        total_seconds += number * units[unit]

        # Move past the unit
        pos += 1

    # Check that we consumed the entire string
    if pos != len(text):
        raise ValueError("invalid format")

    return total_seconds

