def flatten(obj, sep="."):
    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    result = {}

    def _flatten(current, parent_key=""):
        for key, value in current.items():
            # Convert key to string
            str_key = str(key)

            # Build new key
            if parent_key:
                new_key = parent_key + sep + str_key
            else:
                new_key = str_key

            # Handle different value types
            if isinstance(value, dict):
                if not value:  # Empty dict
                    result[new_key] = value
                else:
                    _flatten(value, new_key)
            elif isinstance(value, list):
                if not value:  # Empty list
                    result[new_key] = value
                else:
                    # Process each element in the list
                    for i, item in enumerate(value):
                        list_key = new_key + sep + str(i)
                        if isinstance(item, dict):
                            if not item:  # Empty dict in list
                                result[list_key] = item
                            else:
                                _flatten(item, list_key)
                        elif isinstance(item, list):
                            if not item:  # Empty list in list
                                result[list_key] = item
                            else:
                                # For nested lists, we need to handle them recursively
                                # But we'll treat them as leaves for simplicity
                                result[list_key] = item
                        else:
                            # Other types (including None, tuples, sets, etc.) are leaves
                            result[list_key] = item
            else:
                # Other types are leaves
                result[new_key] = value

    _flatten(obj)
    return result
