function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!str) {
    return str;
  }

  // Insert underscores before uppercase letters that follow lowercase letters or digits
  // Also insert underscores before uppercase letters that follow other uppercase letters
  // when the following character is lowercase (indicating the end of an acronym)
  return str
