function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the input
  const graphCopy = {};
  for (const node in graph) {
    graphCopy[node] = [...graph[node]];
  }

  // Find all tasks (keys and dependencies)
  const allTasks = new Set();
  for (const node in graphCopy) {
    allTasks.add(node);
    for (const dep of graphCopy[node]) {
      allTasks.add(dep);
    }
  }

  // Calculate in-degrees for each task
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = 0;
  }

  for (const node in graphCopy) {
    for (const dep of graphCopy[node]) {
      inDegree[dep]++;
    }
  }

  // Find all nodes with in-degree 0
  const zeroInDegree = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      zeroInDegree.push(task);
    }
  }

  // Sort zero in-degree tasks by name
  zeroInDegree.sort();

  const result = [];

  while (zeroInDegree.length > 0) {
    // Pick the lexicographically smallest task
    const current = zeroInDegree.shift();
    result.push(current);

    // Remove this task and update in-degrees
    for (const node in graphCopy) {
      const index = graphCopy[node].indexOf(current);
      if (index !== -1) {
        graphCopy[node].splice(index, 1);
        inDegree[node]--;
        if (inDegree[node] === 0) {
          zeroInDegree.push(node);
          zeroInDegree.sort();
        }
      }
    }
  }

  // Check for cycles
  for (const task of allTasks) {
    if (inDegree[task] !== 0) {
      throw new Error("cycle");
    }
  }

  return result;
}

