function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the original
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys + dependencies)
  const allTasks = new Set();
  for (const task in graphCopy) {
    allTasks.add(task);
    for (const dep of graphCopy[task]) {
      allTasks.add(dep);
    }
  }

  // Build dependency count for each task
  const depCount = {};
  for (const task of allTasks) {
    depCount[task] = 0;
  }

  // Calculate dependency counts
  for (const task in graphCopy) {
    for (const dep of graphCopy[task]) {
      depCount[dep]++;
    }
  }

  // Find tasks with no dependencies
  const readyTasks = [];
  for (const task of allTasks) {
    if (depCount[task] === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks alphabetically
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Pick the lexicographically smallest task
    const current = readyTasks.shift();
    result.push(current);

    // Remove current task from dependencies
    for (const task in graphCopy) {
      const index = graphCopy[task].indexOf(current);
      if (index !== -1) {
        graphCopy[task].splice(index, 1);
        // Update dependency count
        depCount[task]--;
        // If task now has no dependencies, add to readyTasks
        if (depCount[task] === 0) {
          readyTasks.push(task);
        }
      }
    }

    // Re-sort ready tasks
    readyTasks.sort();
  }

  // Check for cycles
  for (const task of allTasks) {
    if (depCount[task] !== 0) {
      throw new Error('cycle');
    }
  }

  return result;
}

