def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        raise ValueError("empty string")

    # Define unit mappings
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    # Valid unit order
    valid_order = ['d', 'h', 'm', 's']

    # Parse the string
    i = 0
    result = 0
    used_units = set()
    last_unit = None

    while i < len(text):
        # Parse number
        if not text[i].isdigit():
            raise ValueError("invalid number format")

        num_str = ""
        while i < len(text) and text[i].isdigit():
            num_str += text[i]
            i += 1

        if not num_str:
            raise ValueError("missing number")

        try:
            number = int(num_str)
        except ValueError:
            raise ValueError("invalid number format")

        # Parse unit
        if i >= len(text) or text[i] not in units:
            raise ValueError("invalid unit")

        unit = text[i]
        i += 1

        # Check for duplicate units
        if unit in used_units:
            raise ValueError("repeated unit")

        # Check order (must be in descending order)
        if last_unit and valid_order.index(unit) > valid_order.index(last_unit):
            raise ValueError("out-of-order unit")

        # Check for missing unit
        if not unit:
            raise ValueError("missing unit")

        # Add to result
        result += number * units[unit]
        used_units.add(unit)
        last_unit = unit

    # Check if we have a valid unit
    if not last_unit:
        raise ValueError("missing unit")

    return result

