function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the original
  const graphCopy = {};
  for (const node in graph) {
    graphCopy[node] = [...graph[node]];
  }

  // Find all tasks (nodes) in the graph
  const allTasks = new Set();
  for (const node in graphCopy) {
    allTasks.add(node);
    for (const dep of graphCopy[node]) {
      allTasks.add(dep);
    }
  }

  // Calculate in-degrees for each task
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = 0;
  }

  for (const node in graphCopy) {
    for (const dep of graphCopy[node]) {
      inDegree[dep]++;
    }
  }

  // Find all nodes with in-degree 0
  const zeroInDegree = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      zeroInDegree.push(task);
    }
  }

  // Sort the zero in-degree nodes lexicographically
  zeroInDegree.sort();

  const result = [];

  while (zeroInDegree.length > 0) {
    // Pick the smallest node
    const current = zeroInDegree.shift();
    result.push(current);

    // Remove this node from the graph and update in-degrees
    for (const node in graphCopy) {
      const index = graphCopy[node].indexOf(current);
      if (index !== -1) {
        graphCopy[node].splice(index, 1);
        inDegree[node]--;
        if (inDegree[node] === 0) {
          zeroInDegree.push(node);
        }
      }
    }

    // Re-sort the zero in-degree nodes
    zeroInDegree.sort();
  }

  // Check for cycles
  for (const task of allTasks) {
    if (inDegree[task] > 0) {
      throw new Error("cycle");
    }
  }

  return result;
}

