    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    unit_order = ['d', 'h', 'm', 's']

    # Track which units we've seen
    seen_units = set()

    # Parse the string
    i = 0
    total_seconds = 0

    while i < len(text):
        # Parse number
        if not text[i].isdigit():
            raise ValueError("invalid number format")

        num_start = i
        while i < len(text) and text[i].isdigit():
            i += 1

        num_str = text[num_start:i]
        if not num_str:
            raise ValueError("missing number")

        try:
            value = int(num_str)
        except ValueError:
            raise ValueError("invalid number format")

        # Parse unit
        if i >= len(text) or text[i] not in units:
            raise ValueError("missing unit")

        unit = text[i]
        i += 1

        # Check for valid unit order
        if unit not in unit_order:
            raise ValueError("unknown unit")

        # Check if unit was already used
        if unit in seen_units:
            raise ValueError("repeated unit")

        # Check that units appear in descending order
        if seen_units:
            last_unit = None
            for u in unit_order:
                if u in seen_units:
                    last_unit = u
                    break
            if last_unit and unit_order.index(unit) > unit_order.index(last_unit):
                raise ValueError("out-of-order unit")

        seen_units.add(unit)
        total_seconds += value * units[unit]

    # Check that we consumed the entire string
    if i != len(text):
        raise ValueError("invalid format")

    return total_seconds
