  }

  // Check length
  if (cleaned.length < 12 || cleaned.length > 19) {
    return false;
  }

  // Apply Luhn algorithm
  let sum = 0;
  let double = false;

  // Process from right to left
  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned[i]);

    if (double) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }

    sum += digit;
    double = !double;
  }

  // Check if sum is divisible by 10
  return sum % 10 === 0;
}

