function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the input
  const graphCopy = {};
  for (const node in graph) {
    graphCopy[node] = [...graph[node]];
  }

  // Find all nodes that appear as dependencies but never as keys
  const allNodes = new Set();
  for (const node in graphCopy) {
    allNodes.add(node);
    for (const dep of graphCopy[node]) {
      allNodes.add(dep);
    }
  }

  // Calculate in-degrees for each node
  const inDegree = {};
  for (const node of allNodes) {
    inDegree[node] = 0;
  }

  for (const node in graphCopy) {
    for (const dep of graphCopy[node]) {
      inDegree[dep]++;
    }
  }

  // Find all nodes with in-degree 0
  const queue = [];
  for (const node of allNodes) {
    if (inDegree[node] === 0) {
      queue.push(node);
    }
  }

  // Sort queue in ascending order to ensure lexicographic ordering
  queue.sort();

  const result = [];

  while (queue.length > 0) {
    // Pick the smallest node in lexicographic order
    const current = queue.shift();
    result.push(current);

    // Remove current node and update in-degrees
    for (const node in graphCopy) {
      const deps = graphCopy[node];
      const index = deps.indexOf(current);
      if (index !== -1) {
        deps.splice(index, 1);
        inDegree[node]--;
        if (inDegree[node] === 0) {
          queue.push(node);
          queue.sort(); // Keep queue sorted
        }
      }
    }
  }

  // Check for cycles by ensuring all nodes were processed
  if (result.length !== allNodes.size) {
    throw new Error("cycle");
  }

  return result;
}

