    if not isinstance(obj, dict):
        raise TypeError("obj must be a dict")

    result = {}

    def _flatten(current, parent_key=""):
        for key, value in current.items():
            # Convert key to string
            str_key = str(key)

            # Build new key
            if parent_key:
                new_key = parent_key + sep + str_key
            else:
                new_key = str_key

            if isinstance(value, dict):
                # Recursively flatten dictionaries
                _flatten(value, new_key)
            elif isinstance(value, list):
                # Handle lists by iterating through elements
                if not value:  # Empty list
                    result[new_key] = value
                else:
                    for i, item in enumerate(value):
                        list_key = new_key + sep + str(i)
                        if isinstance(item, dict):
                            _flatten(item, list_key)
                        elif isinstance(item, list):
                            # Handle nested lists
                            result[list_key] = item
                        else:
                            # Leaf value
                            result[list_key] = item
            else:
                # Leaf value (including None, tuples, sets, etc.)
                result[new_key] = value

    _flatten(obj)
    return result
