                        list_path = f"{new_path}{sep}{i}"
                        if isinstance(item, (dict, list)):
                            _flatten({str(i): item}, new_path)
                        else:
                            result[list_path] = item
            else:
                result[new_path] = value

    _flatten(obj, "")
