function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError(' qs must be a string');
  }

  // Remove leading '?'
  if (qs.startsWith('?')) {
    qs = qs.substring(1);
  }

  // Empty string case
  if (qs === '') {
    return {};
  }

  const result = {};
  const pairs = qs.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair === '') {
      continue;
    }

    let key;
    let value;

    // Split at first '='
    const firstEquals = pair.indexOf('=');
    if (firstEquals === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, firstEquals);
      value = pair.substring(firstEquals + 1);
    }

    // Decode key and value
    try {
      key = decodeURIComponent(key.replace(/\+/g, ' '));
      value = decodeURIComponent(value.replace(/\+/g, ' '));
    } catch (e) {
      if (e instanceof URIError) {
        throw e;
      }
      throw new URIError('Malformed URI');
    }

    // Skip pairs with empty keys
    if (key === '') {
      continue;
    }

    // Handle multiple values
    if (result.hasOwnProperty(key)) {
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}

