function topoSort(graph) {
  // Create a deep copy of the graph to avoid modifying the input
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys and dependencies)
  const allTasks = new Set();
  for (const task in graphCopy) {
    allTasks.add(task);
    for (const dep of graphCopy[task]) {
      allTasks.add(dep);
    }
  }

  // Calculate in-degrees for each task
  const inDegree = {};
  for (const task of allTasks) {
    inDegree[task] = 0;
  }

  for (const task in graphCopy) {
    for (const dep of graphCopy[task]) {
      inDegree[dep]++;
    }
  }

  // Find all tasks with no dependencies (in-degree = 0)
  const readyTasks = [];
  for (const task of allTasks) {
    if (inDegree[task] === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks by name (string order)
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Pick the task with the smallest name
    const currentTask = readyTasks.shift();
    result.push(currentTask);

    // Remove this task from dependencies of others
    for (const task in graphCopy) {
      const deps = graphCopy[task];
      const index = deps.indexOf(currentTask);
      if (index !== -1) {
        deps.splice(index, 1);
        // Update in-degree for the task that just had a dependency removed
        inDegree[task]--;
        // If in-degree becomes 0, add to ready tasks
        if (inDegree[task] === 0) {
          readyTasks.push(task);
          readyTasks.sort(); // Keep sorted by name
        }
      }
    }
  }

  // Check for cycles: if we haven't processed all tasks, there's a cycle
  if (result.length !== allTasks.size) {
    throw new Error('cycle');
  }

  return result;
}

