function topoSort(graph) {
  // Create a copy of the graph to avoid modifying the input
  const graphCopy = {};
  for (const key in graph) {
    graphCopy[key] = [...graph[key]];
  }

  // Find all tasks (keys and referenced tasks)
  const allTasks = new Set();
  for (const key in graphCopy) {
    allTasks.add(key);
    for (const dep of graphCopy[key]) {
      allTasks.add(dep);
    }
  }

  // Build dependency counts and reverse dependencies
  const depCount = new Map();
  const reverseDeps = new Map();

  for (const task of allTasks) {
    depCount.set(task, 0);
    reverseDeps.set(task, []);
  }

  // Calculate dependency counts and build reverse dependencies
  for (const task in graphCopy) {
    for (const dep of graphCopy[task]) {
      if (task === dep) {
        throw new Error('cycle');
      }
      depCount.set(task, depCount.get(task) + 1);
      reverseDeps.get(dep).push(task);
    }
  }

  // Find all tasks with no dependencies
  const readyTasks = [];
  for (const [task, count] of depCount) {
    if (count === 0) {
      readyTasks.push(task);
    }
  }

  // Sort ready tasks lexicographically
  readyTasks.sort();

  const result = [];

  while (readyTasks.length > 0) {
    // Get the task with smallest name
    const current = readyTasks.shift();
    result.push(current);

    // Remove this task from dependencies
    for (const dependent of reverseDeps.get(current) || []) {
      depCount.set(dependent, depCount.get(dependent) - 1);

      // If this dependent now has no dependencies, add it to ready tasks
      if (depCount.get(dependent) === 0) {
        readyTasks.push(dependent);
        readyTasks.sort(); // Keep sorted
      }
    }
  }

  // Check for cycles
  if (result.length !== allTasks.size) {
    throw new Error('cycle');
  }

  return result;
}

module.exports = { topoSort };
