            raise ValueError("repeated unit")

        # Check for out-of-order units
        if last_unit is not None:
            try:
                last_idx = unit_order.index(last_unit)
                current_idx = unit_order.index(unit)
                if current_idx >= last_idx:
                    raise ValueError("out-of-order unit")
            except ValueError:
                raise ValueError("unknown unit")

        # Check for invalid unit
        if unit not in units:
            raise ValueError("unknown unit")

        # Add to total
        total_seconds += number * units[unit]
        last_unit = unit

    return total_seconds
