function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n) || Number.isNaN(n)) {
    throw new TypeError('n must be a finite number');
  }

  if (n < 0 || !Number.isInteger(n)) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  // Convert to appropriate unit
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Handle rounding to avoid 1024.0 cases
  if (unitIndex < units.length - 1) {
    const roundedValue = Math.round(value * 10) / 10;
    if (roundedValue === 1024) {
      // Move up one unit
      unitIndex++;
      value = 1;
    } else {
      value = roundedValue;
    }
  }

  // Format the result
  if (value % 1 === 0) {
    return `${value} ${units[unitIndex]}`;
  } else {
    // Round to one decimal place and remove trailing zeros
    const formatted = value.toFixed(1);
    return `${formatted.replace(/\.?0+$/, '')} ${units[unitIndex]}`;
  }
}

