function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  // Handle empty or whitespace-only strings
  if (!spec.trim()) {
    return [];
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmedPart = part.trim();

    // Check for empty parts
    if (trimmedPart === '') {
      throw new SyntaxError('Invalid syntax: empty part');
    }

    // Check for invalid characters
    if (!/^[0-9]+$/.test(trimmedPart) && !/^[0-9]+-[0-9]+$/.test(trimmedPart)) {
      throw new SyntaxError('Invalid syntax: malformed part');
    }

    // Handle range
    if (trimmedPart.includes('-')) {
      const [lowStr, highStr] = trimmedPart.split('-');

      // Check for multiple dashes
      if (trimmedPart.split('-').length > 2) {
        throw new SyntaxError('Invalid syntax: multiple dashes');
      }

      // Check for missing end
      if (highStr === '') {
        throw new SyntaxError('Invalid syntax: missing end of range');
      }

      const low = parseInt(lowStr, 10);
      const high = parseInt(highStr, 10);

      // Check for negative numbers
      if (low < 0 || high < 0) {
        throw new SyntaxError('Invalid syntax: negative numbers not allowed');
      }

      // Check for invalid range
      if (low > high) {
        throw new RangeError('Invalid range: start greater than end');
      }

      // Add range to result
      for (let i = low; i <= high; i++) {
        result.add(i);
      }
    } else {
      // Handle single number
      const num = parseInt(trimmedPart, 10);
      if (num < 0) {
        throw new SyntaxError('Invalid syntax: negative numbers not allowed');
      }
      result.add(num);
    }
  }

  // Convert to sorted array
  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
