def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    length = len(line)

    while i < length:
        # Skip whitespace at the beginning of a field
        start = i
        while i < length and line[i] == ' ':
            i += 1

        # Check if we're at a quoted field
        if i < length and line[i] == '"':
            # Find the closing quote
            j = i + 1
            field_content = []
            while j < length:
                if line[j] == '"':
                    # Check if it's a doubled quote
                    if j + 1 < length and line[j + 1] == '"':
                        field_content.append('"')
                        j += 2
                    else:
                        # Found closing quote, check what comes after
                        j += 1
                        if j < length and line[j] != ',' and line[j] != '\n':
                            raise ValueError("quoted field not properly closed")
                        break
                else:
                    field_content.append(line[j])
                    j += 1
            else:
                # No closing quote found
                raise ValueError("quoted field not properly closed")

            result.append(''.join(field_content))
            i = j
        else:
            # Unquoted field
            start = i
            while i < length and line[i] != ',':
                i += 1
            result.append(line[start:i])

        # Move past the comma if present
        if i < length and line[i] == ',':
            i += 1

    return result
