        raise ValueError("Empty string is not valid")

    # Check for invalid characters
    valid_chars = set('IVXLCDM')
    if not all(c in valid_chars for c in s):
        raise ValueError("Invalid character in input")

    # Check for invalid patterns
    invalid_patterns = ['IIII', 'VV', 'XXXX', 'LL', 'CCCC', 'DD', 'MMMM', 'IL', 'IC', 'ID', 'IM', 'XD', 'XM', 'VL', 'VM', 'XD', 'XM']
    for pattern in invalid_patterns:
        if pattern in s:
            raise ValueError("Invalid pattern in input")

    # Check for invalid subtractive combinations
    if 'VV' in s or 'LL' in s or 'DD' in s:
        raise ValueError("Invalid subtractive notation")

    # Check for more than three consecutive same characters
    if 'IIII' in s or 'XXXX' in s or 'CCCC' in s or 'MMMM' in s:
        raise ValueError("More than three consecutive same characters")

    # Check for invalid subtractive pairs
    if 'IL' in s or 'IC' in s or 'ID' in s or 'IM' in s or 'XD' in s or 'XM' in s:
        raise ValueError("Invalid subtractive pair")

    # Define values
    values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    # Convert to integer
    total = 0
    prev_value = 0

    for char in reversed(s):
        current_value = values[char]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value

    # Validate final result
    if total < 1 or total > 3999:
        raise ValueError("Number out of valid range")

    return total
