function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  if (!spec.trim()) {
    return [];
  }

  const parts = spec.split(',').map(part => part.trim());

  // Check for empty parts
  if (parts.includes('')) {
    throw new SyntaxError('Malformed part');
  }

  const result = new Set();

  for (const part of parts) {
    if (part.includes('-')) {
      // Range case
      const rangeParts = part.split('-');

      // Check for multiple dashes or empty range parts
      if (rangeParts.length !== 2 || rangeParts[0] === '' || rangeParts[1] === '') {
        throw new SyntaxError('Malformed part');
      }

      const start = parseInt(rangeParts[0], 10);
      const end = parseInt(rangeParts[1], 10);

      // Check if parsing failed or if negative numbers are present
      if (isNaN(start) || isNaN(end) || start < 0 || end < 0) {
        throw new SyntaxError('Malformed part');
      }

      // Check if start > end
      if (start > end) {
        throw new RangeError('Invalid range');
      }

      for (let i = start; i <= end; i++) {
        result.add(i);
      }
    } else {
      // Single number case
      if (part === '' || /[^\d]/.test(part)) {
        throw new SyntaxError('Malformed part');
      }

      const num = parseInt(part, 10);
      if (isNaN(num) || num < 0) {
        throw new SyntaxError('Malformed part');
      }

      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
