def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    length = len(line)

    while i < length:
        # Skip whitespace before comma
        while i < length and line[i] == ' ':
            i += 1

        if i >= length:
            break

        # Handle quoted field
        if line[i] == '"':
            j = i + 1
            field = ""
            while j < length:
                if line[j] == '"':
                    if j + 1 < length and line[j + 1] == '"':
                        field += '"'
                        j += 2
                    else:
                        # Found closing quote
                        j += 1
                        # Check if next character is valid (comma or end of line)
                        if j < length and line[j] != ',':
                            raise ValueError("Unquoted field")
                        break
                else:
                    field += line[j]
                    j += 1
            else:
                # Unclosed quote
                raise ValueError("Unclosed quote")

            result.append(field)
            i = j
        else:
            # Handle unquoted field
            start = i
            while i < length and line[i] != ',':
                i += 1

            result.append(line[start:i])

        # Skip comma if present
        if i < length and line[i] == ',':
            i += 1

    return result
