  let unitIndex = 0;

  // Convert to appropriate unit
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Handle rounding case where value becomes 1024
  if (value === 1024 && unitIndex < units.length - 1) {
    value = 1;
    unitIndex++;
  }

  // Format the value
  let formattedValue;
  if (value % 1 === 0) {
    formattedValue = value.toString();
  } else {
    // Round to at most one decimal place
    formattedValue = Math.round(value * 10) / 10;
    // Remove trailing .0
    if (formattedValue % 1 === 0) {
      formattedValue = formattedValue.toString();
    } else {
      formattedValue = formattedValue.toFixed(1);
    }
  }

  return `${formattedValue} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
