function formatBytes(n) {
  // Check for valid finite number
  if (typeof n !== 'number' || !Number.isFinite(n) || Number.isNaN(n)) {
    throw new TypeError('n must be a finite number');
  }

  // Check for non-negative integer
  if (n < 0 || !Number.isInteger(n)) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  // Convert to appropriate unit
  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Handle rounding case where value becomes exactly 1024
  if (value === 1024 && unitIndex < units.length - 1) {
    value = 1;
    unitIndex++;
  }

  // Format the result
  if (value % 1 === 0) {
    return `${value} ${units[unitIndex]}`;
  } else {
    // Round to at most one decimal place
    const rounded = Math.round(value * 10) / 10;
    return `${rounded} ${units[unitIndex]}`;
  }
}

