function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  if (!spec.trim()) {
    return [];
  }

  const parts = spec.split(',').map(part => part.trim());

  if (parts.includes('')) {
    throw new SyntaxError('Malformed part');
  }

  const result = new Set();

  for (const part of parts) {
    if (!part) {
      throw new SyntaxError('Malformed part');
    }

    if (part.includes('-')) {
      const rangeParts = part.split('-');

      if (rangeParts.length !== 2) {
        throw new SyntaxError('Malformed part');
      }

      const [lowStr, highStr] = rangeParts;

      if (lowStr === '' || highStr === '') {
        throw new SyntaxError('Malformed part');
      }

      const low = parseInt(lowStr, 10);
      const high = parseInt(highStr, 10);

      if (isNaN(low) || isNaN(high) || low < 0 || high < 0) {
        throw new SyntaxError('Malformed part');
      }

      if (low > high) {
        throw new RangeError('Range start greater than end');
      }

      for (let i = low; i <= high; i++) {
        result.add(i);
      }
    } else {
      const num = parseInt(part, 10);

      if (isNaN(num) || num < 0) {
        throw new SyntaxError('Malformed part');
      }

      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

