def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    while i < len(line):
        # Skip commas at the beginning
        if line[i] == ',':
            result.append("")
            i += 1
            continue

        # Check if quoted field
        if line[i] == '"':
            j = i + 1
            field = ""
            while j < len(line):
                if line[j] == '"':
                    if j + 1 < len(line) and line[j + 1] == '"':
                        field += '"'
                        j += 2
                    else:
                        # Found closing quote
                        k = j + 1
                        # Check what comes after the closing quote
                        if k < len(line) and line[k] not in [',', '\n']:
                            raise ValueError("Quoted field not properly closed")
                        result.append(field)
                        i = k
                        break
                else:
                    field += line[j]
                    j += 1
            else:
                # Never found closing quote
                raise ValueError("Quoted field not properly closed")
        else:
            # Unquoted field
            j = i
            while j < len(line) and line[j] != ',':
                j += 1
            result.append(line[i:j])
            i = j

        # Handle comma
        if i < len(line) and line[i] == ',':
            i += 1

    # Handle trailing comma
    if len(line) > 0 and line[-1] == ',':
        result.append("")

    return result
