      throw new TypeError('Listener must be a function');
    }
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event).push({ fn, once: false });
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('Listener must be a function');
    }
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event).push({ fn, once: true });
    return this;
  }

  off(event, fn) {
    if (!this.listeners.has(event)) {
      return this;
    }
    const eventListeners = this.listeners.get(event);
    const filtered = eventListeners.filter(reg => reg.fn !== fn);
    this.listeners.set(event, filtered);
    return this;
  }

  emit(event, ...args) {
    if (!this.listeners.has(event)) {
      return false;
    }

    const eventListeners = this.listeners.get(event);
    const listenersToCall = [...eventListeners];

    for (let i = 0; i < listenersToCall.length; i++) {
      const reg = listenersToCall[i];
      if (reg.once) {
        // Remove the listener before calling it
        const eventListeners = this.listeners.get(event);
        const index = eventListeners.indexOf(reg);
        if (index !== -1) {
          eventListeners.splice(index, 1);
        }
      }
      reg.fn.apply(this, args);
    }

    return listenersToCall.length > 0;
  }

  listenerCount(event) {
    if (!this.listeners.has(event)) {
      return 0;
    }
    return this.listeners.get(event).length;
  }
}

