function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  if (!spec.trim()) {
    return [];
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmedPart = part.trim();

    if (trimmedPart === '') {
      throw new SyntaxError('Malformed part: empty part');
    }

    if (trimmedPart.includes('.')) {
      throw new SyntaxError('Malformed part: decimal point');
    }

    if (trimmedPart.startsWith('+') || trimmedPart.startsWith('-')) {
      throw new SyntaxError('Malformed part: sign prefix');
    }

    if (trimmedPart.includes('e') || trimmedPart.includes('E')) {
      throw new SyntaxError('Malformed part: scientific notation');
    }

    if (trimmedPart.includes(' ')) {
      throw new SyntaxError('Malformed part: whitespace inside part');
    }

    if (trimmedPart.includes('--')) {
      throw new SyntaxError('Malformed part: multiple dashes');
    }

    if (trimmedPart.startsWith('-') || trimmedPart.endsWith('-')) {
      throw new SyntaxError('Malformed part: missing end');
    }

    if (trimmedPart.includes('-')) {
      const [lowStr, highStr] = trimmedPart.split('-');

      if (lowStr === '' || highStr === '') {
        throw new SyntaxError('Malformed part: missing range bounds');
      }

      const low = parseInt(lowStr, 10);
      const high = parseInt(highStr, 10);

      if (isNaN(low) || isNaN(high)) {
        throw new SyntaxError('Malformed part: non-numeric range bounds');
      }

      if (low < 0 || high < 0) {
        throw new SyntaxError('Malformed part: negative numbers');
      }

      if (low > high) {
        throw new RangeError('Range start greater than end');
      }

      for (let i = low; i <= high; i++) {
        result.add(i);
      }
    } else {
      const num = parseInt(trimmedPart, 10);

      if (isNaN(num)) {
        throw new SyntaxError('Malformed part: non-numeric value');
      }

      if (num < 0) {
        throw new SyntaxError('Malformed part: negative numbers');
      }

      result.add(num);
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
