def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    while i < len(line):
        # Skip commas at the beginning
        if line[i] == ',':
            result.append("")
            i += 1
            continue

        # Handle quoted fields
        if line[i] == '"':
            field = ""
            i += 1  # Skip opening quote
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2  # Skip the escaped quote
                    else:
                        # Found closing quote
                        i += 1  # Skip closing quote
                        # Check if there's a comma or end of line
                        if i < len(line) and line[i] != ',':
                            raise ValueError("Quoted field not properly terminated")
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Quoted field never closed
                raise ValueError("Quoted field not properly terminated")
            result.append(field)
        else:
            # Handle unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                field += line[i]
                i += 1
            result.append(field)

        # Skip comma if present
        if i < len(line) and line[i] == ',':
            i += 1

    # Handle trailing comma
    if len(line) > 0 and line[-1] == ',':
        result.append("")

    return result
