        if line[i] == ',':
            result.append("")
            i += 1
            continue

        # Check if we're at the start of a quoted field
        if line[i] == '"':
            # Find the matching closing quote
            j = i + 1
            field_content = ""
            while j < len(line):
                if line[j] == '"':
                    # Check if it's a doubled quote
                    if j + 1 < len(line) and line[j + 1] == '"':
                        field_content += '"'
                        j += 2
                        continue
                    else:
                        # Found the closing quote
                        # Check that the next character is either comma or end of line
                        if j + 1 < len(line) and line[j + 1] != ',':
                            raise ValueError("Unquoted field must end with comma or end of line")
                        break
                field_content += line[j]
                j += 1
            else:
                # No closing quote found
                raise ValueError("Quoted field is never closed")

            # Add the field content to result
            result.append(field_content)
            i = j + 1  # Move past the closing quote
            # Skip any trailing commas
            while i < len(line) and line[i] == ',':
                result.append("")
                i += 1
        else:
            # Unquoted field
            field_start = i
            while i < len(line) and line[i] != ',':
                i += 1
            result.append(line[field_start:i])
            if i < len(line) and line[i] == ',':
                i += 1

    # Handle trailing commas
    while result and result[-1] == "":
        if len(result) == 1 and result[0] == "":
            break
        if len(result) > 1 and result[-1] == "":
            result.pop()
        else:
            break

    return result
