                if re.match(r'^[0-9]+$', part):
                    if len(part) > 1 and part.startswith('0'):
                        raise ValueError("Invalid version format")
                elif not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError("Invalid version format")

