def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    result = []
    i = 0
    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1  # Skip opening quote
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2  # Skip the escaped quote
                    else:
                        # Closing quote
                        i += 1  # Skip the closing quote
                        # Check for invalid characters after closing quote
                        if i < len(line) and line[i] not in [',', '\n']:
                            raise ValueError("Invalid character after quoted field")
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Unclosed quote
                raise ValueError("Unclosed quoted field")
            result.append(field)
        elif line[i] == ',':
            # Empty field
            result.append("")
            i += 1
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                field += line[i]
                i += 1
            result.append(field)
            if i < len(line) and line[i] == ',':
                i += 1  # Skip comma
    return result
