        min_len = min(len(prerelease_a), len(prerelease_b))
        for i in range(min_len):
            ident_a = prerelease_a[i]
            ident_b = prerelease_b[i]

            # Check if both are numeric
            is_num_a = ident_a.isdigit()
            is_num_b = ident_b.isdigit()

            if is_num_a and is_num_b:
                # Compare as integers
                num_a = int(ident_a)
                num_b = int(ident_b)
                if num_a < num_b:
                    return -1
                elif num_a > num_b:
                    return 1
            elif is_num_a:
                # Numeric has lower precedence
                return -1
            elif is_num_b:
                # Numeric has lower precedence
                return 1
            else:
                # Lexical comparison
                if ident_a < ident_b:
                    return -1
                elif ident_a > ident_b:
                    return 1

        # If all shared identifiers are equal, longer wins
        if len(prerelease_a) < len(prerelease_b):
            return -1
        elif len(prerelease_a) > len(prerelease_b):
            return 1
        else:
            return 0

    # Parse both versions
    try:
        major_a, minor_a, patch_a, prerelease_a = parse_version(a)
        major_b, minor_b, patch_b, prerelease_b = parse_version(b)
    except ValueError:
        raise ValueError("Invalid version format")

    # Compare major, minor, patch
    if major_a < major_b:
        return -1
    elif major_a > major_b:
        return 1
    elif minor_a < minor_b:
        return -1
    elif minor_a > minor_b:
        return 1
    elif patch_a < patch_b:
        return -1
    elif patch_a > patch_b:
        return 1
    else:
        # Same major.minor.patch, compare prerelease
