    in_string = False
    i = 0
    while i < len(code):
        char = code[i]
        if not in_string and char == '"':
            in_string = True
        elif in_string and char == '"':
            if i > 0 and code[i-1] == '\\':
                # Escaped quote, continue as normal
                pass
            else:
                # End of string literal
                in_string = False
        elif not in_string and char in '([{':
            stack.append(char)
        elif not in_string and char in ')]}':
