                return False
            opening = stack.pop()
            if (opening == '(' and char != ')') or \
               (opening == '[' and char != ']') or \
               (opening == '{' and char != '}'):
                return False
        i += 1

    # If we have unclosed brackets, it's unbalanced
    if stack:
        return False

    # If we're still in a string, it's unbalanced
    if in_string:
        return False

    return True
