    throw new TypeError('days must be an integer');
  }

  // Validate date string format
  const dateRegex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(dateRegex);
  if (!match) {
    throw new RangeError('dateStr must be in YYYY-MM-DD format');
  }

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  // Validate year range
  if (year < 1 || year > 9999) {
    throw new RangeError('year must be between 0001 and 9999');
  }

  // Validate month and day
  if (month < 1 || month > 12) {
    throw new RangeError('month must be between 01 and 12');
  }

  // Check if the date is valid
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || 
      date.getUTCMonth() !== month - 1 || 
      date.getUTCDate() !== day) {
    throw new RangeError('dateStr must be a valid calendar date');
  }

  // Add days
  date.setUTCDate(date.getUTCDate() + days);

  // Check if result year is valid
  const resultYear = date.getUTCFullYear();
  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('result year must be between 0001 and 9999');
  }

  // Format result
  const resultMonth = String(date.getUTCMonth() + 1).padStart(2, '0');
  const resultDay = String(date.getUTCDate()).padStart(2, '0');
  return `${resultYear.toString().padStart(4, '0')}-${resultMonth}-${resultDay}`;
}

