  function memoized(...args) {
    const key = keyFn ? keyFn(...args) : args[0];
    if (cache.has(key)) {
      return cache.get(key);
    }

    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  }

  memoized.clear = function() {
    cache.clear();
  };

  return memoized;
}

