def wrap_text(text, width):
    if not isinstance(width, int):
        raise TypeError("width must be an int")
    if width < 1:
        raise ValueError("width must be at least 1")

    # Split into words, ignoring leading/trailing whitespace
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        # Check if word is longer than width
        if len(word) > width:
            # If we have a line in progress, save it first
            if current_line:
                lines.append(" ".join(current_line))
            # Add the long word as a line by itself
            lines.append(word)
            current_line = []
            current_length = 0
        else:
            # Check if word fits in current line
            if current_line and current_length + 1 + len(word) > width:
                # Save current line and start new one
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = len(word)
            else:
                # Add word to current line
                if current_line:
                    current_length += 1 + len(word)
                else:
                    current_length = len(word)
                current_line.append(word)

    # Don't forget the last line
    if current_line:
        lines.append(" ".join(current_line))

    return lines
