function memoize(fn, keyFn = null) {
  if (typeof fn !== 'function') {
    throw new TypeError('fn must be a function');
  }

  if (keyFn !== null && typeof keyFn !== 'function') {
    throw new TypeError('keyFn must be a function or null');
