    current_line = []
    current_length = 0

    for word in words:
        # Calculate length if we add this word
        word_length = len(word)

        # If word is longer than width, it goes alone
        if word_length > width:
            if current_line:
                lines.append(" ".join(current_line))
            lines.append(word)
            current_line = []
            current_length = 0
        else:
            # Check if word fits on current line
            if current_line and current_length + 1 + word_length > width:
                # Start new line
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = word_length
            else:
                # Add to current line
                if current_line:
                    current_length += 1 + word_length  # +1 for space
                else:
                    current_length = word_length
                current_line.append(word)

    # Add remaining line if any
    if current_line:
