  // Check if birthday has occurred this year
  const birthMonth = birthDate.getMonth();
  const birthDay = birthDate.getDate();
  const onMonth = onDate.getMonth();
  const onDay = onDate.getDate();

  // For February 29th birthdays, adjust for non-leap years
  if (birthMonth === 1 && birthDay === 29) {
    // Check if current year is leap year
    const isCurrentYearLeap = (onDate.getFullYear() % 4 === 0 && onDate.getFullYear() % 100 !== 0) || 
                             (onDate.getFullYear() % 400 === 0);

    // If not leap year and we're in February, birthday hasn't happened yet
    if (!isCurrentYearLeap && onMonth === 1) {
      age--;
