    }
    // If we're on March 1st or later in a non-leap year, birthday hasn't happened yet
    else if (!isCurrentYearLeap && onMonth === 1 && onDay >= 1) {
      age--;
    }
  } else {
    // For regular birthdays, check if this year's birthday has passed
    if (onMonth < birthMonth || (onMonth === birthMonth && onDay < birthDay)) {
      age--;
    }
  }

  return age;
}

