def maze_steps(grid):
    if not grid:
        raise ValueError("Invalid grid")

    # Check uniform row lengths
    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("Rows must be of equal length")

    # Find start and end positions, validate characters
    start = None
    end = None
    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char not in "SE#.":
                raise ValueError("Invalid character in grid")
            if char == 'S':
                if start is not None:
                    raise ValueError("Multiple start positions")
                start = (i, j)
            elif char == 'E':
                if end is not None:
                    raise ValueError("Multiple end positions")
                end = (i, j)

    if start is None or end is None:
        raise ValueError("Missing start or end position")

    # BFS to find shortest path
    queue = deque([(start[0], start[1], 0)])  # (row, col, steps)
    visited = set()
    visited.add(start)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        row, col, steps = queue.popleft()

        if (row, col) == end:
            return steps

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check bounds
            if 0 <= new_row < len(grid) and 0 <= new_col < row_len:
                # Check if cell is accessible (not a wall) and not visited
                if (new_row, new_col) not in visited and grid[new_row][new_col] != '#':
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, steps + 1))

    return -1
