def maze_steps(grid):
    if not grid:
        raise ValueError("Invalid grid")

    # Check grid validity
    row_len = len(grid[0])
    for row in grid:
        if len(row) != row_len:
            raise ValueError("Invalid grid")
        for char in row:
            if char not in "SE#.":
                raise ValueError("Invalid character in grid")

    # Find start and end positions
    start = None
    end = None
    s_count = 0
    e_count = 0

    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char == 'S':
                s_count += 1
                start = (i, j)
            elif char == 'E':
                e_count += 1
                end = (i, j)

    if s_count != 1 or e_count != 1:
        raise ValueError("Grid must contain exactly one start and one end")

    # BFS to find shortest path
    queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
    visited = set()
    visited.add(start)

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    while queue:
        row, col, dist = queue.popleft()

        if (row, col) == end:
            return dist

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check bounds
            if 0 <= new_row < len(grid) and 0 <= new_col < row_len:
                # Check if cell is accessible
                if grid[new_row][new_col] in ".E" and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, dist + 1))

    return -1
