  if (birthDate.toString() === 'Invalid Date' || onDate.toString() === 'Invalid Date') {
    throw new RangeError('Invalid date');
  }

  // Validate birth date is not after on date
  if (onDate < birthDate) {
    throw new RangeError('on date cannot be earlier than birth date');
  }

  // Extract year, month, day
  const birthYear = birthDate.getFullYear();
  const birthMonth = birthDate.getMonth();
  const birthDay = birthDate.getDate();

  const onYear = onDate.getFullYear();
  const onMonth = onDate.getMonth();
  const onDay = onDate.getDate();

  // Calculate initial age
  let age = onYear - birthYear;

  // Check if birthday has occurred this year
  // For February 29, if it's not a leap year, birthday is March 1
  if (birthMonth === 1 && birthDay === 29) {
    // Check if current year is leap year
    const isLeapYear = (onYear % 4 === 0 && onYear % 100 !== 0) || (onYear % 400 === 0);
    if (!isLeapYear) {
      // If not leap year, birthday is March 1
      if (onMonth < 2 || (onMonth === 2 && onDay < 1)) {
