def maze_steps(grid):
    if not grid:
        raise ValueError("Invalid grid")

    # Check that all rows have the same length
    row_length = len(grid[0])
    for row in grid:
        if len(row) != row_length:
            raise ValueError("Rows must have equal length")

    # Find start and end positions, validate characters
    start_pos = None
    end_pos = None
    valid_chars = {'S', 'E', '#', '.'}

    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char not in valid_chars:
                raise ValueError("Invalid character in grid")
            if char == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple start positions")
                start_pos = (i, j)
            elif char == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple end positions")
                end_pos = (i, j)

    if start_pos is None:
        raise ValueError("No start position found")
    if end_pos is None:
        raise ValueError("No end position found")

    # BFS to find shortest path
    queue = deque([(start_pos[0], start_pos[1], 0)])  # (row, col, steps)
    visited = set()
    visited.add(start_pos)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while queue:
        row, col, steps = queue.popleft()

        if (row, col) == end_pos:
            return steps

        for dr, dc in directions:
