def maze_steps(grid):
    if not grid:
        raise ValueError("Invalid grid")

    # Check if all rows have the same length
    row_length = len(grid[0])
    for row in grid:
        if len(row) != row_length:
            raise ValueError("All rows must have the same length")

    # Find start and end positions, and validate characters
    start_pos = None
    end_pos = None
    for i, row in enumerate(grid):
        for j, char in enumerate(row):
            if char not in 'SE#.':
                raise ValueError("Invalid character in grid")
            if char == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple start positions")
                start_pos = (i, j)
            elif char == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple end positions")
                end_pos = (i, j)

    if start_pos is None or end_pos is None:
        raise ValueError("Missing start or end position")

    # BFS to find shortest path
    queue = deque([(start_pos[0], start_pos[1], 0)])  # (row, col, steps)
    visited = set()
    visited.add(start_pos)

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    while queue:
        row, col, steps = queue.popleft()

        if (row, col) == end_pos:
            return steps

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check bounds
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]):
                # Check if cell is open (including start/end) or is exit
                if (new_row, new_col) not in visited and grid[new_row][new_col] != '#':
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, steps + 1))

    return -1
