function longestCommonPrefix(strs) {
  // Type checking
  if (!Array.isArray(strs)) {
    throw new TypeError('Argument must be an array');
  }

  for (let i = 0; i < strs.length; i++) {
    if (typeof strs[i] !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  // Handle edge cases
  if (strs.length === 0) {
    return '';
  }

  if (strs.length === 1) {
    return strs[0];
  }

  // Find the shortest string to limit our comparison
  let minLength = strs[0].length;
  for (let i = 1; i < strs.length; i++) {
    if (strs[i].length < minLength) {
      minLength = strs[i].length;
    }
  }

  // Compare character by character
  let prefix = '';

  for (let i = 0; i < minLength; i++) {
    // Get the character at position i from the first string
    const char = strs[0].codePointAt(i);

    // Check if all other strings have the same character at position i
    let allMatch = true;
    for (let j = 1; j < strs.length; j++) {
      // Check if the character at position i matches
      if (strs[j].codePointAt(i) !== char) {
        allMatch = false;
        break;
      }
    }

    if (allMatch) {
      // Add the character to prefix
      prefix += String.fromCodePoint(char);
    } else {
      break;
    }
  }

  return prefix;
}

